CREATE OR REPLACE FUNCTION public.guard_profile_customer_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF (TG_OP = 'INSERT' AND NEW.customer_id IS NOT NULL) OR (TG_OP = 'UPDATE' AND NEW.customer_id IS DISTINCT FROM OLD.customer_id) THEN IF auth.uid() IS NOT NULL AND coalesce(auth.role(),'') <> 'service_role' AND NOT coalesce(public.is_master_admin(auth.uid()),false) THEN RAISE EXCEPTION 'Only administrators can link client accounts'; END IF; END IF; RETURN NEW; END $$;